tool_input.command:
cat >> src/components/signature/blueprint.tsx <<'EOF'

/** Landing pages: the slabs lift once when the drawing is 30% in view (never under reduced motion). */
export function LiftingBlueprint(props: BlueprintProps) {
  const ref = useRef<SVGSVGElement>(null);
  const { inView } = useEntry(ref, 0.3);
  return <Blueprint ref={ref} {...props} className={[props.className, inView && 'is-lifted'].filter(Boolean).join(' ')} />;
}
EOF
